import { useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

export interface AppearanceSettings {
  theme: string;
  scale: number;
  dense: boolean;
  fontFamily: string;
}

interface AppearanceSettingsScreenProps {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_ITEMS = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONT_OPTIONS = [
  { value: 'sans', label: 'Inter Tight', meta: 'по умолчанию' },
  { value: 'display', label: 'Fraunces', meta: 'заголовочный' },
  { value: 'mono', label: 'JetBrains Mono', meta: 'моноширинный' },
];

const INITIAL: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  fontFamily: 'sans',
};

export default function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    ...INITIAL,
    ...defaultValue,
  });

  const update = (patch: Partial<AppearanceSettings>) => {
    const next = { ...settings, ...patch };
    setSettings(next);
    onChange?.(next);
  };

  const themeLabel =
    THEME_ITEMS.find((item) => item.value === settings.theme)?.label ?? 'Системная';

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '24px',
        maxWidth: '560px',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '16px',
          flexWrap: 'wrap',
        }}
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
          <h1
            style={{
              margin: 0,
              fontFamily: 'var(--jx-font-display)',
              fontSize: '24px',
              color: 'var(--jx-text)',
            }}
          >
            Внешний вид
          </h1>
          <p style={{ margin: 0, fontSize: '14px', color: 'var(--jx-text-2)' }}>
            Настройки применяются сразу и сохраняются для этого устройства.
          </p>
        </div>
        <JxBadge tone="accent" dot>
          {themeLabel}
        </JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <span style={{ fontSize: '14px', color: 'var(--jx-text-2)' }}>Тема оформления</span>
        <JxToggle
          items={THEME_ITEMS}
          value={settings.theme}
          onValueChange={(theme) => update({ theme })}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={5}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(scale) => update({ scale })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.dense}
        onChange={(event) => update({ dense: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт интерфейса"
        placeholder="Выберите шрифт"
        options={FONT_OPTIONS}
        value={settings.fontFamily}
        onValueChange={(fontFamily) => update({ fontFamily })}
      />
    </section>
  );
}

